/**
 * Renders a translated string that contains a handful of trusted inline tags
 * (<strong>, <a>) as markup instead of literal text. The value always comes
 * from our own locale JSON, never user input, so this is safe the same way
 * ArticleBody's dangerouslySetInnerHTML is.
 */
export default function Rich({ text, as: Tag = 'span', className }) {
  return <Tag className={className} dangerouslySetInnerHTML={{ __html: text }} />;
}
